targets.expr:
sum by (job, jvm_gc_name, jvm_gc_action) (
  rate(jvm_gc_duration_seconds_sum{
    job=~"((minecraft|proxy)/)?$job",
    instance=~"$instance"
  }[5m])
)

sum by (job, jvm_thread_state) (
  jvm_thread_count{
    job=~"((minecraft|proxy)/)?$job",
    instance=~"$instance"
  }
)

sum by (job, detected_level) (
  rate({exporter="OTLP", job=~"((minecraft|proxy)/)?$job"} | detected_level=~"$level" [$__interval])
) * 60
